<?php
declare(strict_types=1);
require dirname(__DIR__).'/ai-lib.php';
$u=require_login();$cid=(int)$u['company_id'];$uid=(int)$u['id'];$action=(string)($_GET['action']??'settings');$method=(string)($_SERVER['REQUEST_METHOD']??'GET');if($method!=='GET')verify_csrf();
try{
 switch($action){
