  case 'models':require_cap_v10('admin.settings.read');$cfg=ai_settings($cid);if($cfg['provider']!=='local')json_response(['ok'=>false,'error'=>'local_provider_required'],422);json_response(['ok'=>true,'items'=>ai_list_models($cfg)]);
