  case 'usage':require_cap_v10('admin.settings.read');$cfg=ai_settings($cid);$st=db()->prepare('SELECT DATE(a.created_at) usage_date,a.user_id,u.name user_name,COUNT(*) calls,SUM(a.success) successes,SUM(a.tokens_in) tokens_in,SUM(a.tokens_out) tokens_out,ROUND(SUM(a.tokens_in)*?/1000000+SUM(a.tokens_out)*?/1000000,6) estimated_cost FROM v10_ai_calls a LEFT JOIN users u ON u.id=a.user_id WHERE a.company_id=? GROUP BY DATE(a.created_at),a.user_id,u.name ORDER BY usage_date DESC,user_name LIMIT 1000');$st->execute([(float)$cfg['input_cost_per_million'],(float)$cfg['output_cost_per_million'],$cid]);json_response(['ok'=>true,'items'=>$st->fetchAll()]);
  case 'call':
    $b=str_starts_with((string)($_SERVER['CONTENT_TYPE']??''),'multipart/form-data')?$_POST:body_json();$feature=clean_status((string)($b['feature']??''),['summarize','draft_reply','quote_read','translate','next_step'],'');if($feature==='')json_response(['ok'=>false,'error'=>'unknown_ai_feature'],422);$cfg=ai_settings($cid);if($cfg['provider']==='off')json_response(['ok'=>false,'error'=>'ai_off','message'=>'AI is turned off.'],422);if(empty($cfg['features'][$feature]))json_response(['ok'=>false,'error'=>'feature_disabled','message'=>'This AI feature is disabled.'],403);
