    else{$text=trim((string)($b['text']??''));if($text==='')json_response(['ok'=>false,'error'=>'text_required'],422);$context=['text'=>mb_substr($text,0,50000)];if($feature==='draft_reply')$context['instruction']=mb_substr(trim((string)($b['instruction']??'')),0,500);if($entity&&$entityId)$context['record']=ai_record_context($entity,$entityId,$cid,$u);if($feature==='translate')$context['target_language']=(string)($b['target_language']??(($u['lang']??'fa')==='fa'?'en':'fa'));}
    $r=ai_call($cfg,$feature,$context,$u['lang']??'fa',$cid,$uid,$entity?:null,$entityId?:null,$feature==='quote_read');if($feature==='quote_read')json_response(['ok'=>true,'draft'=>$r['json']]);json_response(['ok'=>true,'draft'=>$r['content']]);
  default:json_response(['ok'=>false,'error'=>'unknown_action'],404);
 }
}catch(Throwable$e){error_log($e->__toString());$msg=$e->getMessage();json_response(['ok'=>false,'error'=>'ai_failed','message'=>$msg!==''?$msg:'AI request failed. The page remains usable.'],502);}
